`default_nettype none
`include "defines.sv"

// free input variables, can take any value each cycle as long as the `assume` are satisfied
module testbench (
	input check,
	input clock, reset
);
	`RVFI_WIRES
	`RVFI_BUS_WIRES

	`RISCV_FORMAL_CHECKER checker_inst (
		.clock  (clock),
		.reset  (reset),
		.check   (check),
		`RVFI_CONN
		`RVFI_BUS_CONN
	);

	// Ignore rvfi_order loopback, otherwise the check might be invalid.
	reg rvfi_order_loopback;
	always @(posedge clock) begin
		if (reset) begin
			rvfi_order_loopback <= 0;
		end else if (rvfi_valid && rvfi_order == {64{1'b1}}) begin
			rvfi_order_loopback <= 1;
		end
	end
	always_comb assume (!(rvfi_order_loopback && check));

	rvfi_wrapper wrapper (
		.clock (clock),
		.reset (reset),
		`RVFI_CONN
		`RVFI_BUS_CONN
	);

/// Helper Assertion Begin
// A non-causal flag can only become true after the global order has
// surpassed the selected instruction order, and then it must remain so.
always @(posedge clock) begin
	if (!reset) begin
		h_found_non_causal_after_order: assert(!checker_inst.found_non_causal ||
			(checker_inst.rvfi_order > checker_inst.insn_order));
	end
end
/// Helper Assertion End
endmodule

`default_nettype none
`include "defines.sv"

// free input variables, can take any value each cycle as long as the `assume` are satisfied
module testbench (
	input check,
	input clock, reset
);
	`RVFI_WIRES
	`RVFI_BUS_WIRES

	`RISCV_FORMAL_CHECKER checker_inst (
		.clock  (clock),
		.reset  (reset),
		.check   (check),
		`RVFI_CONN
		`RVFI_BUS_CONN
	);

	// Ignore rvfi_order loopback, otherwise the check might be invalid.
	reg rvfi_order_loopback;
	always @(posedge clock) begin
		if (reset) begin
			rvfi_order_loopback <= 0;
		end else if (rvfi_valid && rvfi_order == {64{1'b1}}) begin
			rvfi_order_loopback <= 1;
		end
	end
	always_comb assume (!(rvfi_order_loopback && check));

	rvfi_wrapper wrapper (
		.clock (clock),
		.reset (reset),
		`RVFI_CONN
		`RVFI_BUS_CONN
	);

/// Helper Assertion Begin
// Track whether the global order has ever surpassed the selected instruction
// order. This avoids wrap-around issues in pure order comparisons.
reg h_order_gt_insn;
always @(posedge clock) begin
	if (reset) begin
		h_order_gt_insn <= 1'b0;
	end else if (checker_inst.rvfi_order > checker_inst.insn_order) begin
		h_order_gt_insn <= 1'b1;
	end
end

// A non-causal flag can only be true after rvfi_order has surpassed insn_order.
always @(posedge clock) begin
	if (!reset) begin
		h_found_non_causal_after_order: assert(!checker_inst.found_non_causal || h_order_gt_insn);
	end
end
/// Helper Assertion End
endmodule
